import java.util.ArrayList;
import java.util.List;

public final class Solution {
    private Solution() {}

    public interface BatchListener {
        void onBatch(List<String> statements);
        void onRejected(int index, String statement);
    }

    public interface Completion {
        void onComplete(int accepted, int rejected);
    }

    public static void submit(String[] statements, int batchSize,
                              BatchListener listener, Completion completion) {
        List<String> batch = new ArrayList<>();
        int accepted = 0;
        int rejected = 0;

        for (int i = 0; i < statements.length; i++) {
            String statement = statements[i];
            if (statement == null) {
                listener.onRejected(i, statement);
                rejected++;
                continue;
            }

            batch.add(statement);
            accepted++;
            if (batch.size() == batchSize) {
                listener.onBatch(batch);
                batch = new ArrayList<>();
            }
        }

        if (!batch.isEmpty()) {
            listener.onBatch(batch);
        }
        completion.onComplete(accepted, rejected);
    }
}
